    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / max(1, len(good))
    return out

def make_weights(score):
    # Full-investment, long-only, modest 2.5%-14% bounds for a 15-asset universe.
    lo, hi = .025, .14
    raw = {s: max(.08, score.get(s, .5)) for s in UNIVERSE}
    w = {s: lo + (hi - lo) * raw[s] / max(raw.values()) for s in UNIVERSE}
    for _ in range(30):
        over = [s for s in UNIVERSE if w[s] > hi]
        if not over:
            break
        w = {s: min(hi, w[s]) for s in UNIVERSE}
        rem = 1.0 - sum(w.values())
        eligible = [s for s in UNIVERSE if w[s] < hi - 1e-12]
        z = sum(raw[s] for s in eligible)
        for s in eligible:
