    breadth = np.mean([r20[s] > 0 for s in px])
    spx = px.get('SPX')
    bear = spx is not None and spx[-1] < spx[-21] and spx[-1] < spx[-6]
    if bear or breadth < .45:
        for s in ('XAU', 'US10Y', 'CN10Y'):
            score[s] += .16
        for s in ('BTC', 'ETH', 'WTI'):
            score[s] -= .08
    # Inverse volatility is only a sizing overlay; all 15 targets remain funded.
